class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        max_len = 0
        n, m = len(s), len(t)

        # Generate all substrings of s and t, including the empty string
        subs_s = [""]
        for i in range(n):
            for j in range(i, n):
                subs_s.append(s[i:j+1])

        subs_t = [""]
        for i in range(m):
            for j in range(i, m):
                subs_t.append(t[i:j+1])

        # Try every concatenation of a substring from s and a substring from t
        for a in subs_s:
            la = len(a)
            for b in subs_t:
                lb = len(b)
                if la + lb <= max_len:
                    continue
                x = a + b
                if x == x[::-1]:
                    max_len = la + lb

        return max_len
