from typing import List

class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # Precompute powers of 4 and prefix sums of full blocks
        pow4 = [1]
        while pow4[-1] <= 10**9:
            pow4.append(pow4[-1] * 4)

        # pref[k] = sum_{j=1}^{k} j * (pow4[j] - pow4[j-1])
        pref = [0]
        for k in range(1, len(pow4)):
            cnt = pow4[k] - pow4[k - 1]
            pref.append(pref[-1] + k * cnt)

        def get_k(x: int) -> int:
            """Return k such that pow4[k-1] <= x < pow4[k] (i.e. f(x) = k)."""
            k = 1
            while k < len(pow4) and x >= pow4[k]:
                k += 1
            return k

        def prefix_sum(x: int) -> int:
            """Sum_{i=1}^{x} f(i), where f(i) is the number of divisions by 4 to reach 0."""
            if x == 0:
                return 0
            k = get_k(x)
            # full blocks up to k-1, plus partial block for value k
            return pref[k - 1] + k * (x - pow4[k - 1] + 1)

        def f(x: int) -> int:
            if x == 0:
                return 0
            return get_k(x)

        total = 0
        for l, r in queries:
            S = prefix_sum(r) - prefix_sum(l - 1)
            M = f(r)                     # maximum f(x) in [l, r] is at r (f is non-decreasing)
            ops = max((S + 1) // 2, M)   # min operations = max(ceil(S/2), M)
            total += ops
        return total
