class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Build a segment tree over basket capacities.
        # Use size as the next power of two for a simple complete binary tree.
        size = 1
        while size < n:
            size <<= 1
        tree = [0] * (2 * size)

        # Leaves: original baskets, padding with 0 (unused and low capacity)
        for i in range(n):
            tree[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[2 * i], tree[2 * i + 1])

        def update(idx: int, val: int) -> None:
            """Mark basket idx as used by setting its capacity to 0."""
            p = size + idx
            tree[p] = val
            p >>= 1
            while p:
                tree[p] = max(tree[2 * p], tree[2 * p + 1])
                p >>= 1

        def query_first(x: int) -> int:
            """Return the leftmost basket index with capacity >= x, or -1."""
            if tree[1] < x:
                return -1
            node = 1
            l, r = 0, size - 1
            while l < r:
                mid = (l + r) // 2
                if tree[node * 2] >= x:
                    node = node * 2
                    r = mid
                else:
                    node = node * 2 + 1
                    l = mid + 1
            # l == r is a leaf index
            if l < n and tree[node] >= x:
                return l
            return -1

        unplaced = 0
        for x in fruits:
            idx = query_first(x)
            if idx == -1:
                unplaced += 1
            else:
                update(idx, 0)  # basket now occupied

        return unplaced
